/* { dg-output "OK" } */

package aaa;

// An exception range that covers another try's catch block protects that
// block too.  javac splits such a range at the handler; Kawa doesn't (its
// guard compiles this way), so the class is assembled by hand (generated by
// a small script; version 49, so it needs no StackMapTable):
//
//   static int f() {
//      0: aconst_null  1: athrow       ; caught by the inner catch-all, [0,2) -> 2
//      2: pop  3: iconst_1  4: iconst_0  5: idiv   ; ArithmeticException in the handler
//      6: ireturn
//      7: pop  8: iconst_2  9: ireturn  ; outer handler, [0,7) -> 7 ArithmeticException
//   }
//
// OpenLDK emitted the inner handler outside the outer range's HANDLER-CASE,
// so the ArithmeticException escaped f instead of returning 2.
public class handlerrange extends ClassLoader
{
    private static final byte[] RANGES = new byte[] {
        -54,-2,-70,-66,0,0,0,49,0,10,1,0,23,97,97,97,47,104,97,110,100,108,101,114,114,97,110,103,101,36,82,97,110,103,101,115,7,0,1,1,0,16,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,7,0,3,1,0,29,106,97,118,97,47,108,97,110,103,47,65,114,105,116,104,109,101,116,105,99,69,120,99,101,112,116,105,111,110,7,0,5,1,0,4,67,111,100,101,1,0,1,102,1,0,3,40,41,73,0,33,0,2,0,4,0,0,0,0,0,1,0,9,0,8,0,9,0,1,0,7,0,0,0,38,0,2,0,0,0,0,0,10,1,-65,87,4,3,108,-84,87,5,-84,0,2,0,0,0,2,0,2,0,0,0,0,0,7,0,7,0,6,0,0,0,0
    };

    protected Class<?> findClass(String name) throws ClassNotFoundException
    {
        if (!name.equals("aaa.handlerrange$Ranges")) throw new ClassNotFoundException(name);
        return defineClass(name, RANGES, 0, RANGES.length);
    }

    public static void main(String[] args) throws Exception
    {
        Class<?> ranges = new handlerrange().loadClass("aaa.handlerrange$Ranges");
        Object result;
        try { result = ranges.getMethod("f").invoke(null); }
        catch (java.lang.reflect.InvocationTargetException e) { result = "escaped: " + e.getCause(); }
        catch (Throwable t) { result = "escaped: " + t; }
        System.out.println(Integer.valueOf(2).equals(result) ? "OK" : "FAIL: " + result);
    }
}
